import {useState, useEffect, type ChangeEventHandler, useEffectEvent} from 'react'
import {FormControl, Select} from '@primer/react'
import {callMsGraphResourceGroups} from '../graph'
import type {IResourceGroupPickerProps} from '../types/virtual-network-settings-types'
import styles from './ResourceGroupPicker.module.css'
interface IResourceGroupProps {
  readonly id: string
  readonly name: string
}

export function ResourceGroupPicker({
  accessToken,
  selectedSubscription,
  resourceGroupError,
  setAppState,
  onError,
}: IResourceGroupPickerProps) {
  const [resourceGroups, setResourceGroups] = useState([])

  const handleError = useEffectEvent(onError)
  const updateResourceGroups = useEffectEvent(async () => {
    if (!accessToken) {
      return
    }

    if (selectedSubscription) {
      const response = await callMsGraphResourceGroups(accessToken, selectedSubscription.id)

      setResourceGroups(
        response.value.map(({id, name}: IResourceGroupProps) => {
          return {
            id,
            name,
          }
        }),
      )

      if (response.value.length > 0) {
        setAppState(previousAppState => ({...previousAppState, selectedResourceGroup: response.value[0].id}))
      } else {
        setAppState(previousAppState => ({...previousAppState, selectedResourceGroup: null}))
      }
    } else {
      setAppState(previousAppState => ({...previousAppState, selectedResourceGroup: null}))
    }
  })

  useEffect(() => {
    try {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      updateResourceGroups()
    } catch (e) {
      // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
      handleError(e)
    }
  }, [accessToken, selectedSubscription])

  const handleChange: ChangeEventHandler<HTMLSelectElement> = e => {
    setAppState(previousAppState => ({...previousAppState, selectedResourceGroup: e.target.value}))
  }

  const options = resourceGroups.map(({id, name}) => {
    return (
      <Select.Option key={id} value={id}>
        {name}
      </Select.Option>
    )
  })

  return (
    <FormControl required className={styles.FormControl}>
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <FormControl.Label>Resource Group</FormControl.Label>
      <Select block onChange={handleChange} aria-invalid={!!resourceGroupError}>
        {options}
      </Select>
      {!!resourceGroupError && <FormControl.Validation variant="error">{resourceGroupError}</FormControl.Validation>}
    </FormControl>
  )
}
